package org.rabochaya.projects;
import java.io.*;import java.security.*;import java.util.*;
/** Explicit, bounded project raster job. Progress is advisory; resume verifies every cached tile. */
public final class CompositionDownloadJob {
 public static final class Task {public final TileSource source;public final int z,x,y;Task(TileSource s,int[] t){source=s;z=t[0];x=t[1];y=t[2];}}
 public final MapComposition composition;public final double west,south,east,north;public final int min,max,completed;public final String generation;public final List<Task> tasks;private final String sourceStamp;
 public CompositionDownloadJob(MapComposition c,double w,double s,double e,double n,int min,int max){this(c,w,s,e,n,min,max,0,UUID.randomUUID().toString(),null);}
 private CompositionDownloadJob(MapComposition c,double w,double s,double e,double n,int min,int max,int done,String generation,String expected){
  if(c==null||min<0||max>23||min>max||generation==null||!generation.matches("[a-f0-9-]{36}"))throw new IllegalArgumentException("Проверьте состав и масштабы задания");new TileRegion(w,s,e,n,0,0);
  composition=c;west=w;south=s;east=e;north=n;this.min=min;this.max=max;this.generation=generation;
  LinkedHashMap<String,Task> unique=new LinkedHashMap<>();StringBuilder stamp=new StringBuilder();
  for(MapComposition.Layer layer:c.layers)if(layer.visible&&layer.opacity>0){TileSource source=layer.source();if(source==null){if("catalog".equals(layer.kind)||"custom".equals(layer.kind))throw new IllegalArgumentException("Источник больше не найден: "+layer.name);continue;}
   for(TileSource leaf:source.leafs()){int lo=Math.max(min,leaf.minZoom),hi=Math.min(max,leaf.maxZoom);if(lo>hi)continue;stamp.append(leaf.id).append(':').append(lo).append(':').append(hi).append(':').append(leaf.ellipsoid).append('\n');TileDownloadPlan plan=new TileDownloadPlan(leaf,w,s,e,n,lo,hi);for(int[] tile:plan.regions[0]){String key=leaf.id+"/"+tile[0]+"/"+tile[1]+"/"+tile[2];if(!unique.containsKey(key))unique.put(key,new Task(leaf,tile));if(unique.size()>TileRegion.MAX_TILES)throw new IllegalArgumentException("В составе больше 20 000 уникальных тайлов");}}
  }
  if(unique.isEmpty()||done<0||done>unique.size())throw new IllegalArgumentException("Нет доступных онлайн-слоёв в выбранных масштабах");tasks=Collections.unmodifiableList(new ArrayList<>(unique.values()));sourceStamp=hash(stamp.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));if(expected!=null&&!expected.equals(sourceStamp))throw new IllegalArgumentException("Каталог источников изменён; создайте новое задание");completed=done;
 }
 private CompositionDownloadJob(CompositionDownloadJob base,int done){if(done<0||done>base.tasks.size())throw new IllegalArgumentException("Неверный прогресс задания");composition=base.composition;west=base.west;south=base.south;east=base.east;north=base.north;min=base.min;max=base.max;completed=done;generation=base.generation;tasks=base.tasks;sourceStamp=base.sourceStamp;}
 public CompositionDownloadJob progress(int done){return new CompositionDownloadJob(this,done);}
 public boolean matches(MapComposition current)throws IOException{if(current==null||current.project!=composition.project)return false;Set<String> ids=new HashSet<>();for(MapComposition.Layer l:composition.layers)ids.add(l.id);List<MapComposition.Layer> selected=new ArrayList<>();for(MapComposition.Layer l:current.layers)if(ids.contains(l.id))selected.add(l);return MessageDigest.isEqual(composition.encode(),new MapComposition(current.project,selected).encode());}
 private static String hash(byte[] bytes){try{StringBuilder text=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))text.append(String.format(Locale.US,"%02x",b&255));return text.toString();}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 public byte[] encode()throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){out.writeInt(0x524b444a);out.writeInt(1);out.writeLong(composition.project);byte[] c=composition.encode();out.writeInt(c.length);out.write(c);out.writeDouble(west);out.writeDouble(south);out.writeDouble(east);out.writeDouble(north);out.writeInt(min);out.writeInt(max);out.writeInt(completed);out.writeUTF(generation);out.writeUTF(sourceStamp);}byte[] body=bytes.toByteArray();bytes.write(hash(body).getBytes("US-ASCII"));return bytes.toByteArray();}
 public static CompositionDownloadJob decode(byte[] bytes,long project)throws IOException{if(bytes==null||bytes.length<150||bytes.length>132000)throw new IOException("Недопустимый размер задания");byte[] body=Arrays.copyOf(bytes,bytes.length-64);if(!MessageDigest.isEqual(hash(body).getBytes("US-ASCII"),Arrays.copyOfRange(bytes,bytes.length-64,bytes.length)))throw new IOException("Задание повреждено; сохранённый кеш не изменён");try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(body))){if(in.readInt()!=0x524b444a||in.readInt()!=1||in.readLong()!=project)throw new IOException("Задание другого проекта/версии");int length=in.readInt();if(length<52||length>131072||length>in.available())throw new IOException("Повреждён состав задания");byte[] c=new byte[length];in.readFully(c);CompositionDownloadJob job=new CompositionDownloadJob(MapComposition.decode(c,project),in.readDouble(),in.readDouble(),in.readDouble(),in.readDouble(),in.readInt(),in.readInt(),in.readInt(),in.readUTF(),in.readUTF());if(in.available()!=0)throw new IOException("Лишние данные задания");return job;}catch(IllegalArgumentException e){throw new IOException("Не удалось восстановить задание: "+e.getMessage(),e);}}
}
